//! Capability Hygiene: generation and fail-closed verification of the multi-agent closures
//! that keep every `Seat` inside the single Hotpot control plane.
//!
//! Closures are generated by `hotpot setup` into each Role Home and re-checked fail-closed by
//! `hotpot verify` (and by `setup` itself before applying anything):
//!
//! - **Codex**: the operator's model catalog (`$HOME/.codex/models.json`, a read-only input)
//!   is projected into each Codex Role Home as `models.json` with every `multi_agent_version`
//!   key removed recursively (an absent operator catalog projects a minimal empty catalog; an
//!   unparseable one fails closed — no scrubbed catalog can be produced). The seat
//!   `config.json` disables `agents.enabled` and every `features.multi_agent*` flag in both
//!   the top-level scope and the active profile scope.
//! - **Claude**: the canonical native-orchestration deny list is pinned in each Role Home
//!   `settings.json` (`disallowedTools`) and repeated in the launch flags, alongside the
//!   Agent View / dynamic workflows / `claude.ai` connectors disable flags.
//! - **Pi**: each Role Home launch config records exactly
//!   `--no-extensions --extension builtin:mcp --extension builtin:codemode --no-approve`, and
//!   `hotpot verify` probes the (injectable, offline) `pi` binary asserting `/mcp` resolves
//!   strictly to `builtin:mcp`.
//! - **Operator MCP inspection**: the operator MCP configs (`$HOME/.codex/mcp.json`,
//!   `$HOME/.claude/mcp.json`, `$HOME/.pi/agent/mcp.json`) are read without mutation; any
//!   server recognizably named or commanded as a `hotpot`/`paseo` orchestration server fails
//!   `setup` and `verify` before anything is applied.

use crate::provisioner::{PlanError, find_on_path};
use serde_json::{Value, json};
use std::env;
use std::fs;
use std::path::Path;
use std::process::Command;

/// The catalog key whose presence anywhere advertises native multi-agent support.
pub const CODEX_MULTI_AGENT_VERSION_KEY: &str = "multi_agent_version";

/// Name of the (single) active profile pinned in every generated Codex seat config.
pub const CODEX_ACTIVE_PROFILE: &str = "default";

/// Claude's canonical native-orchestration deny list: the `Task`, `Agent`, and `Workflow`
/// spawning tools plus the coordination, cron, and team tools. Pinned in every Claude Role
/// Home `settings.json` (`disallowedTools`) and repeated in the launch flags.
pub const CLAUDE_DENY_TOOLS: &[&str] = &["Task", "Agent", "Workflow", "Coordination", "Cron", "Team"];

/// The Claude launch-flag form of the deny list: one `--disallow-tool <Tool>` pair per tool.
pub fn claude_deny_launch_args() -> Vec<String> {
    let mut args = Vec::new();
    for tool in CLAUDE_DENY_TOOLS {
        args.push("--disallow-tool".to_string());
        args.push((*tool).to_string());
    }
    args
}

/// The Claude closure settings merged into each Role Home `settings.json`: the full deny list
/// plus the Agent View, dynamic workflows, and `claude.ai` connectors disable flags.
pub fn claude_closure_settings() -> Value {
    json!({
        "disallowedTools": CLAUDE_DENY_TOOLS,
        "enableAgentView": false,
        "enableDynamicWorkflows": false,
        "enableClaudeAiConnectors": false,
    })
}

/// The Pi launch args closing every native extension except the two approved builtins and
/// requiring explicit approval: exactly
/// `--no-extensions --extension builtin:mcp --extension builtin:codemode --no-approve`.
pub const PI_LAUNCH_ARGS: &[&str] = &[
    "--no-extensions",
    "--extension",
    "builtin:mcp",
    "--extension",
    "builtin:codemode",
    "--no-approve",
];

/// The Pi Role Home launch config recording exactly [`PI_LAUNCH_ARGS`] as file contents.
pub fn pi_launch_config_contents() -> String {
    serde_json::to_string_pretty(&json!({ "args": PI_LAUNCH_ARGS })).unwrap() + "\n"
}

/// Operator MCP config files inspected for orchestration-server backdoors (read-only).
pub const OPERATOR_MCP_CONFIGS: &[&str] = &[".codex/mcp.json", ".claude/mcp.json", ".pi/agent/mcp.json"];

/// The operator's Codex model catalog (read-only input); absent → a minimal empty catalog,
/// unparseable → fail closed (a scrubbed catalog cannot be produced).
pub fn operator_codex_catalog() -> Result<Value, PlanError> {
    let empty = json!({ "models": [] });
    let Some(home) = env::var_os("HOME") else {
        return Ok(empty);
    };
    let path = Path::new(&home).join(".codex").join("models.json");
    match fs::read_to_string(&path) {
        Err(_) => Ok(empty),
        Ok(text) => serde_json::from_str(&text).map_err(|e| {
            PlanError::new(
                "codex-catalog-scrub",
                format!(
                    "operator catalog {} is not valid JSON, so no scrubbed catalog can be produced: {e}",
                    path.display()
                ),
            )
        }),
    }
}

/// Removes every `multi_agent_version` key recursively (objects and arrays), preserving all
/// other content — the scrub applied when projecting the operator catalog into a seat.
pub fn scrub_catalog(value: &Value) -> Value {
    match value {
        Value::Object(map) => {
            let mut out = serde_json::Map::new();
            for (key, inner) in map {
                if key == CODEX_MULTI_AGENT_VERSION_KEY {
                    continue;
                }
                out.insert(key.clone(), scrub_catalog(inner));
            }
            Value::Object(out)
        }
        Value::Array(items) => Value::Array(items.iter().map(scrub_catalog).collect()),
        other => other.clone(),
    }
}

/// The scrubbed catalog as file contents (pretty JSON, trailing newline).
pub fn scrubbed_catalog_contents(catalog: &Value) -> String {
    serde_json::to_string_pretty(&scrub_catalog(catalog)).unwrap() + "\n"
}

/// The Codex closure settings merged into each seat's `config.json`: `agents.enabled = false`
/// and every `features.multi_agent*` flag disabled, in both the top-level scope and the
/// active profile scope (`profile` names it).
pub fn codex_closure_settings() -> Value {
    let closed_scope = || json!({ "agents": { "enabled": false }, "features": { "multi_agent": false } });
    let mut profiles = serde_json::Map::new();
    profiles.insert(CODEX_ACTIVE_PROFILE.to_string(), closed_scope());
    json!({
        "agents": { "enabled": false },
        "features": { "multi_agent": false },
        "profile": CODEX_ACTIVE_PROFILE,
        "profiles": Value::Object(profiles),
    })
}

// ---------------------------------------------------------------------------
// Fail-closed verification
// ---------------------------------------------------------------------------

/// Stable check names printed by `hotpot verify` (and by `setup`'s pre-apply gate).
pub const CHECK_CODEX_CATALOG: &str = "codex-catalog-scrubbed";
pub const CHECK_CODEX_AGENTS: &str = "codex-agents-disabled";
pub const CHECK_CLAUDE_DENY: &str = "claude-deny-list";
pub const CHECK_CLAUDE_FLAGS: &str = "claude-disable-flags";
pub const CHECK_PI_LAUNCH: &str = "pi-launch-args";
pub const CHECK_PI_PROBE: &str = "pi-mcp-probe";
pub const CHECK_OPERATOR_MCP: &str = "operator-mcp-clean";

/// Which caller is running the checks.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CheckMode {
    /// `setup`'s pre-apply gate: existing seat closure files are checked and any violation
    /// aborts before applying; files that do not exist yet are skipped (the plan is about to
    /// create them closed). The Pi RPC probe is not run.
    PreApply,
    /// `hotpot verify`: a missing closure file is a failure (the path is not verifiably
    /// closed), and the offline Pi RPC probe runs against the `pi` binary found on `PATH`.
    Verify,
}

/// One executed check instance: a stable `name` plus a human-readable `detail`.
#[derive(Debug)]
pub struct CheckResult {
    pub name: &'static str,
    pub ok: bool,
    pub detail: String,
}

impl CheckResult {
    fn ok(name: &'static str, detail: impl Into<String>) -> Self {
        Self {
            name,
            ok: true,
            detail: detail.into(),
        }
    }

    fn fail(name: &'static str, detail: impl Into<String>) -> Self {
        Self {
            name,
            ok: false,
            detail: detail.into(),
        }
    }

    /// The report line: ok lines belong on stdout, FAIL lines on stderr.
    pub fn render(&self) -> String {
        let verdict = if self.ok { "ok" } else { "FAIL" };
        format!("verify: {verdict} {} {}", self.name, self.detail)
    }
}

/// A seat closure file as loaded from disk.
enum SeatFile {
    Missing,
    Invalid,
    Loaded(Value),
}

fn load_seat_json(path: &Path) -> SeatFile {
    match fs::read_to_string(path) {
        Err(_) => SeatFile::Missing,
        Ok(text) => serde_json::from_str(&text).map(SeatFile::Loaded).unwrap_or(SeatFile::Invalid),
    }
}

/// The single check outcome for a seat file, honoring the mode: missing files skip silently
/// before apply (the plan recreates them) but fail verification.
fn checked_missing(mode: CheckMode, name: &'static str, rel: &str) -> Option<CheckResult> {
    match mode {
        CheckMode::PreApply => None,
        CheckMode::Verify => Some(CheckResult::fail(
            name,
            format!("{rel} is missing (run `hotpot setup --apply` first)"),
        )),
    }
}

/// True when `key` appears in any object nested under `value` (objects and arrays).
fn contains_key_recursive(value: &Value, key: &str) -> bool {
    match value {
        Value::Object(map) => {
            map.contains_key(key) || map.values().any(|inner| contains_key_recursive(inner, key))
        }
        Value::Array(items) => items.iter().any(|inner| contains_key_recursive(inner, key)),
        _ => false,
    }
}

/// Runs every Capability Hygiene check over the Hotpot Home (and the read-only operator
/// inputs): per-seat closure checks for all nine Role Homes, the Pi RPC probe (`Verify`
/// mode only), and the operator MCP inspection. One [`CheckResult`] per check instance.
pub fn run_checks(home: &Path, mode: CheckMode) -> Vec<CheckResult> {
    let mut results = Vec::new();
    for role in crate::provisioner::ROLES {
        results.extend(check_codex_catalog(home, role, mode));
        results.extend(check_codex_agents_disabled(home, role, mode));
        results.extend(check_claude_deny_list(home, role, mode));
        results.extend(check_claude_disable_flags(home, role, mode));
        results.extend(check_pi_launch_args(home, role, mode));
        if mode == CheckMode::Verify {
            results.push(check_pi_mcp_probe(role));
        }
    }
    results.extend(check_operator_mcp());
    results
}

/// `codex-catalog-scrubbed`: the seat's projected `models.json` must parse and carry no
/// `multi_agent_version` key anywhere.
fn check_codex_catalog(home: &Path, role: &str, mode: CheckMode) -> Vec<CheckResult> {
    let rel = format!("roles/codex/{role}/models.json");
    match load_seat_json(&home.join(&rel)) {
        SeatFile::Missing => checked_missing(mode, CHECK_CODEX_CATALOG, &rel).into_iter().collect(),
        SeatFile::Invalid => {
            vec![CheckResult::fail(CHECK_CODEX_CATALOG, format!("{rel} is not valid JSON"))]
        }
        SeatFile::Loaded(catalog) => {
            if contains_key_recursive(&catalog, CODEX_MULTI_AGENT_VERSION_KEY) {
                vec![CheckResult::fail(
                    CHECK_CODEX_CATALOG,
                    format!(
                        "{rel} still contains {CODEX_MULTI_AGENT_VERSION_KEY}; the model catalog is not scrubbed"
                    ),
                )]
            } else {
                vec![CheckResult::ok(
                    CHECK_CODEX_CATALOG,
                    format!("{rel} carries no {CODEX_MULTI_AGENT_VERSION_KEY}"),
                )]
            }
        }
    }
}

/// The first closure violation of one Codex config scope, if any: `agents.enabled` must be
/// false, `features` must exist, and every `features.multi_agent*` flag — starting with the
/// canonical `multi_agent` flag — must be false.
fn codex_scope_violation(scope: &Value) -> Option<String> {
    if scope["agents"]["enabled"].as_bool() != Some(false) {
        return Some("agents.enabled is not disabled".to_string());
    }
    let Some(features) = scope["features"].as_object() else {
        return Some("features scope is missing".to_string());
    };
    if !features.contains_key("multi_agent") {
        return Some("features.multi_agent is not pinned to false".to_string());
    }
    features
        .iter()
        .filter(|(key, _)| key.starts_with("multi_agent"))
        .find_map(|(key, value)| {
            (value.as_bool() != Some(false)).then(|| format!("features.{key} is not disabled"))
        })
}

/// `codex-agents-disabled`: both the top-level scope and the active profile scope of the
/// seat's `config.json` must disable agents and every `features.multi_agent*` flag.
fn check_codex_agents_disabled(home: &Path, role: &str, mode: CheckMode) -> Vec<CheckResult> {
    let rel = format!("roles/codex/{role}/config.json");
    match load_seat_json(&home.join(&rel)) {
        SeatFile::Missing => checked_missing(mode, CHECK_CODEX_AGENTS, &rel).into_iter().collect(),
        SeatFile::Invalid => vec![CheckResult::fail(
            CHECK_CODEX_AGENTS,
            format!("{rel} is not valid JSON"),
        )],
        SeatFile::Loaded(config) => {
            if let Some(reason) = codex_scope_violation(&config) {
                return vec![CheckResult::fail(
                    CHECK_CODEX_AGENTS,
                    format!("{rel} top-level scope: {reason}"),
                )];
            }
            let Some(active) = config["profile"].as_str() else {
                return vec![CheckResult::fail(
                    CHECK_CODEX_AGENTS,
                    format!("{rel} declares no active profile (profile field missing)"),
                )];
            };
            let profile = &config["profiles"][active];
            if !profile.is_object() {
                return vec![CheckResult::fail(
                    CHECK_CODEX_AGENTS,
                    format!("{rel} active profile `{active}` is missing"),
                )];
            }
            if let Some(reason) = codex_scope_violation(profile) {
                return vec![CheckResult::fail(
                    CHECK_CODEX_AGENTS,
                    format!("{rel} profile `{active}` scope: {reason}"),
                )];
            }
            vec![CheckResult::ok(
                CHECK_CODEX_AGENTS,
                format!("{rel} top-level and profile `{active}` scopes disable agents and every features.multi_agent* flag"),
            )]
        }
    }
}

/// The string entries recorded under `scope[key]`, if that field is a JSON array.
fn string_array(scope: &Value, key: &str) -> Option<Vec<String>> {
    scope[key]
        .as_array()
        .map(|items| {
            items
                .iter()
                .map(|v| v.as_str().unwrap_or_default().to_string())
                .collect()
        })
}

/// `claude-deny-list`: the full canonical deny list in `settings.json`'s `disallowedTools`
/// and repeated as `--disallow-tool <Tool>` launch flags in `launch.json`.
fn check_claude_deny_list(home: &Path, role: &str, mode: CheckMode) -> Vec<CheckResult> {
    let settings_rel = format!("roles/claude/{role}/settings.json");
    let launch_rel = format!("roles/claude/{role}/launch.json");
    let settings = match load_seat_json(&home.join(&settings_rel)) {
        SeatFile::Missing => {
            return checked_missing(mode, CHECK_CLAUDE_DENY, &settings_rel)
                .into_iter()
                .collect()
        }
        SeatFile::Invalid => {
            return vec![CheckResult::fail(
                CHECK_CLAUDE_DENY,
                format!("{settings_rel} is not valid JSON"),
            )]
        }
        SeatFile::Loaded(value) => value,
    };
    let launch = match load_seat_json(&home.join(&launch_rel)) {
        SeatFile::Missing => {
            return checked_missing(mode, CHECK_CLAUDE_DENY, &launch_rel)
                .into_iter()
                .collect()
        }
        SeatFile::Invalid => {
            return vec![CheckResult::fail(
                CHECK_CLAUDE_DENY,
                format!("{launch_rel} is not valid JSON"),
            )]
        }
        SeatFile::Loaded(value) => value,
    };

    let Some(denied) = string_array(&settings, "disallowedTools") else {
        return vec![CheckResult::fail(
            CHECK_CLAUDE_DENY,
            format!("{settings_rel} disallowedTools must be an array"),
        )];
    };
    for tool in CLAUDE_DENY_TOOLS {
        if !denied.iter().any(|entry| entry == tool) {
            return vec![CheckResult::fail(
                CHECK_CLAUDE_DENY,
                format!("{settings_rel} disallowedTools is missing the \"{tool}\" entry"),
            )];
        }
    }
    let args = string_array(&launch, "args").unwrap_or_default();
    for tool in CLAUDE_DENY_TOOLS {
        let pinned = args
            .windows(2)
            .any(|w| w[0] == "--disallow-tool" && w[1] == *tool);
        if !pinned {
            return vec![CheckResult::fail(
                CHECK_CLAUDE_DENY,
                format!("{launch_rel} is missing the --disallow-tool \"{tool}\" flag"),
            )];
        }
    }
    vec![CheckResult::ok(
        CHECK_CLAUDE_DENY,
        format!("{settings_rel} and {launch_rel} carry the full native-orchestration deny list"),
    )]
}

/// `claude-disable-flags`: Agent View, dynamic workflows, and `claude.ai` connectors must
/// each be explicitly disabled in the seat's `settings.json`.
fn check_claude_disable_flags(home: &Path, role: &str, mode: CheckMode) -> Vec<CheckResult> {
    let rel = format!("roles/claude/{role}/settings.json");
    match load_seat_json(&home.join(&rel)) {
        SeatFile::Missing => checked_missing(mode, CHECK_CLAUDE_FLAGS, &rel).into_iter().collect(),
        SeatFile::Invalid => {
            vec![CheckResult::fail(CHECK_CLAUDE_FLAGS, format!("{rel} is not valid JSON"))]
        }
        SeatFile::Loaded(settings) => {
            for flag in ["enableAgentView", "enableDynamicWorkflows", "enableClaudeAiConnectors"] {
                if settings[flag].as_bool() != Some(false) {
                    return vec![CheckResult::fail(
                        CHECK_CLAUDE_FLAGS,
                        format!("{rel} {flag} is not disabled"),
                    )];
                }
            }
            vec![CheckResult::ok(
                CHECK_CLAUDE_FLAGS,
                format!("{rel} disables agent view, dynamic workflows, and claude.ai connectors"),
            )]
        }
    }
}

/// `pi-launch-args`: the seat's `launch.json` must record exactly [`PI_LAUNCH_ARGS`].
fn check_pi_launch_args(home: &Path, role: &str, mode: CheckMode) -> Vec<CheckResult> {
    let rel = format!("roles/pi/{role}/launch.json");
    match load_seat_json(&home.join(&rel)) {
        SeatFile::Missing => checked_missing(mode, CHECK_PI_LAUNCH, &rel).into_iter().collect(),
        SeatFile::Invalid => vec![CheckResult::fail(CHECK_PI_LAUNCH, format!("{rel} is not valid JSON"))],
        SeatFile::Loaded(launch) => {
            let args = string_array(&launch, "args").unwrap_or_default();
            let expected: Vec<String> = PI_LAUNCH_ARGS.iter().map(|s| s.to_string()).collect();
            if args == expected {
                vec![CheckResult::ok(
                    CHECK_PI_LAUNCH,
                    format!("{rel} pins exactly the closed extension launch args"),
                )]
            } else {
                vec![CheckResult::fail(
                    CHECK_PI_LAUNCH,
                    format!("{rel} must record exactly {expected:?}, got {args:?}"),
                )]
            }
        }
    }
}

/// `pi-mcp-probe`: launches the `pi` binary found on `PATH` with exactly the closed launch
/// args plus `rpc /mcp` (an offline RPC probe — never the network) and asserts `/mcp`
/// resolves strictly to `builtin:mcp`.
fn check_pi_mcp_probe(role: &str) -> CheckResult {
    let seat = format!("roles/pi/{role}");
    let Some(pi) = find_on_path("pi") else {
        return CheckResult::fail(
            CHECK_PI_PROBE,
            format!("pi is not on PATH; cannot probe /mcp resolution for {seat}"),
        );
    };
    let output = Command::new(&pi)
        .args(PI_LAUNCH_ARGS)
        .args(["rpc", "/mcp"])
        .output();
    let Ok(output) = output else {
        return CheckResult::fail(
            CHECK_PI_PROBE,
            format!("failed to run the pi RPC probe for {seat}"),
        );
    };
    if !output.status.success() {
        return CheckResult::fail(
            CHECK_PI_PROBE,
            format!(
                "pi RPC probe for {seat} exited with {}",
                output.status.code().unwrap_or(-1)
            ),
        );
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    let report: Value = match serde_json::from_str(stdout.trim()) {
        Ok(value) => value,
        Err(_) => {
            return CheckResult::fail(
                CHECK_PI_PROBE,
                format!("pi RPC probe for {seat} returned unparseable output: {}", stdout.trim()),
            )
        }
    };
    let extensions = string_array(&report, "extensions").unwrap_or_default();
    let expected: Vec<String> = vec!["builtin:mcp".to_string()];
    if extensions == expected {
        CheckResult::ok(
            CHECK_PI_PROBE,
            format!("{seat} /mcp resolves strictly to builtin:mcp"),
        )
    } else {
        CheckResult::fail(
            CHECK_PI_PROBE,
            format!(
                "pi RPC probe for {seat} reported /mcp resolving to {extensions:?}; expected strictly [\"builtin:mcp\"]"
            ),
        )
    }
}

/// `operator-mcp-clean`: reads the operator MCP configs under `$HOME` without mutating them
/// and fails when any configured server is recognizably a hotpot/paseo orchestration server
/// (name/command heuristics).
fn check_operator_mcp() -> Vec<CheckResult> {
    let Some(home) = env::var_os("HOME") else {
        return vec![CheckResult::ok(
            CHECK_OPERATOR_MCP,
            "HOME is not set; no operator MCP configs to inspect",
        )];
    };
    let root = Path::new(&home);
    let mut failures = Vec::new();
    let mut inspected = 0usize;
    for rel in OPERATOR_MCP_CONFIGS {
        let path = root.join(rel);
        let Ok(text) = fs::read_to_string(&path) else {
            continue;
        };
        inspected += 1;
        let config: Value = match serde_json::from_str(&text) {
            Ok(value) => value,
            Err(_) => {
                failures.push(CheckResult::fail(
                    CHECK_OPERATOR_MCP,
                    format!("{rel} is not valid JSON; cannot inspect it for orchestration servers"),
                ));
                continue;
            }
        };
        for (name, server) in config["mcpServers"].as_object().into_iter().flatten() {
            let command = server["command"].as_str().unwrap_or("");
            if is_orchestration_server(name, command) {
                failures.push(CheckResult::fail(
                    CHECK_OPERATOR_MCP,
                    format!(
                        "{rel}: server \"{name}\" (command \"{command}\") is recognizably a hotpot/paseo orchestration server"
                    ),
                ));
            }
        }
    }
    if failures.is_empty() {
        vec![CheckResult::ok(
            CHECK_OPERATOR_MCP,
            format!("no hotpot/paseo orchestration servers among the operator MCP configs ({inspected} inspected)"),
        )]
    } else {
        failures
    }
}

/// Recognizable orchestration server: the server name or its command string mentions
/// `hotpot` or `paseo` (case-insensitive) — e.g. a `hotpot mcp` stdio server.
fn is_orchestration_server(name: &str, command: &str) -> bool {
    let name = name.to_lowercase();
    let command = command.to_lowercase();
    ["hotpot", "paseo"]
        .iter()
        .any(|marker| name.contains(marker) || command.contains(marker))
}
